import 'package:flutter/foundation.dart';
import 'package:uuid/uuid.dart';
import 'memory.dart';
import 'memory_repository.dart';
class MemoryEngine { final MemoryRepository _repository; final Uuid _uuid = const Uuid(); final ValueNotifier<MemoryStats> statsNotifier = ValueNotifier(MemoryStats.empty()); final ValueNotifier<int> _version = ValueNotifier(0); ValueNotifier<int> get version => _version; MemoryEngine({required MemoryRepository repository}) : _repository = repository; Future<void> initialize() async { await _refresh(); } Future<void> _refresh() async { statsNotifier.value = MemoryStats(total: await _repository.count(), lastUpdate: DateTime.now()); _version.value++; } Future<Memory> remember({required String content, required String conversationId, Map<String, dynamic> metadata = const {}}) async { final id = _uuid.v4(); final memory = Memory(id: id, content: content, conversationId: conversationId, metadata: metadata); final result = await _repository.save(memory); await _refresh(); return result; } Future<List<Memory>> getByConversation(String conversationId) { return _repository.getByConversation(conversationId); } Future<List<Memory>> getAll() { return _repository.getAll(); } Future<List<Memory>> search(String query) { return _repository.search(query); } }
